function hasExplicitDarkThemeCss(styleSource, selector) {
  const escapedSelector = selector.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`:root\\[data-theme="dark"\\][\\s\\S]*${escapedSelector}`).test(styleSource) ||
    new RegExp(`\\.c-config-provider\\[data-theme="dark"\\][\\s\\S]*${escapedSelector}`).test(styleSource);
}

