const MIND_MAP_CONNECTOR_INSPECTOR = String.raw`
      const inspectMindMapConnectors = (svg) => {
        const round = (value) => Math.round(value * 100) / 100;
        const rectOfConnector = (rect) => ({
          left: round(rect.left),
          top: round(rect.top),
          right: round(rect.right),
          bottom: round(rect.bottom),
          width: round(rect.width),
          height: round(rect.height),
        });
        const parsePointPath = (d) => {
          const commands = d.match(/[AaCcHhLlMmQqSsTtVvZz]/g) ?? [];
          const nums = (d.match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi) ?? []).map(Number);
          return {
            commandOk: commands.length === 2 && commands[0] === "M" && commands[1] === "C",
            commands,
            start: nums.length >= 2 ? { x: nums[0], y: nums[1] } : null,
            c1: nums.length >= 4 ? { x: nums[2], y: nums[3] } : null,
            c2: nums.length >= 6 ? { x: nums[4], y: nums[5] } : null,
            end: nums.length >= 8 ? { x: nums[6], y: nums[7] } : null,
          };
        };
        const matrix = svg.getScreenCTM();
        const toScreen = (point) => {
          if (!point || !matrix) return null;
          const svgPoint = svg.createSVGPoint();
          svgPoint.x = point.x;
          svgPoint.y = point.y;
          const transformed = svgPoint.matrixTransform(matrix);
          return { x: transformed.x, y: transformed.y };
        };
        const centerX = (rect) => rect.left + rect.width / 2;
        const centerY = (rect) => rect.top + rect.height / 2;
        const pointDeepInside = (point, rect) =>
          Boolean(point) &&
          point.x > rect.left + 4 &&
          point.x < rect.right - 4 &&
          point.y > rect.top + 4 &&
          point.y < rect.bottom - 4;
        const edgeDistance = (point, rect, side) => ({
          edge: point ? round(Math.abs(point.x - (side === "right" ? rect.right : rect.left))) : Number.POSITIVE_INFINITY,
          center: point ? round(Math.abs(point.y - centerY(rect))) : Number.POSITIVE_INFINITY,
          insideDeep: pointDeepInside(point, rect),
        });
        const pointInRect = (point, rect, pad = 0) =>
          Boolean(point) &&
          point.x >= rect.left - pad &&
          point.x <= rect.right + pad &&
          point.y >= rect.top - pad &&
          point.y <= rect.bottom + pad;
        const nodeEntries = Array.from(svg.querySelectorAll(".c-mind-map__node"))
          .map((node) => {
            const id = node.getAttribute("data-node-id");
            const box = node.querySelector(".c-mind-map__node-box");
            return id && box ? [id, { box: rectOfConnector(box.getBoundingClientRect()) }] : null;
          })
          .filter(Boolean);
        const nodesById = new Map(nodeEntries);
        const avoidRects = Array.from(svg.querySelectorAll(".c-mind-map__node-label, .c-mind-map__node-value, .c-mind-map__toggle circle")).map((item) => {
          const owner = item.closest(".c-mind-map__node");
          return {
            text: item.textContent?.trim() || item.getAttribute("class") || item.tagName,
            ownerId: owner?.getAttribute("data-node-id") ?? null,
            isToggle: item.matches(".c-mind-map__toggle circle"),
            rect: rectOfConnector(item.getBoundingClientRect()),
          };
        });
        const reports = Array.from(svg.querySelectorAll(".c-mind-map__links path")).map((path, index) => {
          const d = path.getAttribute("d") ?? "";
          const parsed = parsePointPath(d);
          const style = getComputedStyle(path);
          const attrStrokeWidth = Number.parseFloat(path.getAttribute("stroke-width") ?? "");
          const computedStrokeWidth = Number.parseFloat(style.strokeWidth);
          const strokeWidth = Number.isFinite(attrStrokeWidth) ? attrStrokeWidth : computedStrokeWidth;
          const parentId = path.getAttribute("data-parent-id");
          const childId = path.getAttribute("data-child-id");
          const parent = parentId ? nodesById.get(parentId) : null;
          const child = childId ? nodesById.get(childId) : null;
          const start = toScreen(parsed.start);
          const end = toScreen(parsed.end);
          const childIsRight = parent && child ? centerX(child.box) >= centerX(parent.box) : true;
          const startSide = childIsRight ? "right" : "left";
          const endSide = childIsRight ? "left" : "right";
          const startDistance = parent ? edgeDistance(start, parent.box, startSide) : null;
          const endDistance = child ? edgeDistance(end, child.box, endSide) : null;
          const endpointOk =
            Boolean(parent && child && startDistance && endDistance) &&
            startDistance.edge <= 2.75 &&
            startDistance.center <= 2.75 &&
            !startDistance.insideDeep &&
            endDistance.edge <= 2.75 &&
            endDistance.center <= 2.75 &&
            !endDistance.insideDeep;
          const minX = parsed.start && parsed.end ? Math.min(parsed.start.x, parsed.end.x) : 0;
          const maxX = parsed.start && parsed.end ? Math.max(parsed.start.x, parsed.end.x) : 0;
          const controlOk =
            Boolean(parsed.start && parsed.c1 && parsed.c2 && parsed.end) &&
            parsed.c1.x >= minX - 0.01 &&
            parsed.c1.x <= maxX + 0.01 &&
            parsed.c2.x >= minX - 0.01 &&
            parsed.c2.x <= maxX + 0.01 &&
            Math.abs(parsed.c1.y - parsed.start.y) <= 0.01 &&
            Math.abs(parsed.c2.y - parsed.end.y) <= 0.01;
          let labelOverlap = null;
          try {
            const totalLength = path.getTotalLength();
            for (let step = 1; step < 18 && !labelOverlap; step += 1) {
              const point = toScreen(path.getPointAtLength((totalLength * step) / 18));
              const hit = avoidRects.find(
                (item) =>
                  !(item.isToggle && (item.ownerId === parentId || item.ownerId === childId)) &&
                  pointInRect(point, item.rect, item.isToggle ? -3 : 1),
              );
              if (hit) labelOverlap = { step, text: hit.text, rect: hit.rect, point: point ? { x: round(point.x), y: round(point.y) } : null };
            }
          } catch {
            labelOverlap = { error: "path length unavailable" };
          }
          const markerIssue = ["marker-start", "marker-mid", "marker-end"].some((name) => path.getAttribute(name));
          const styleOk =
            Number.isFinite(strokeWidth) &&
            strokeWidth >= 1.9 &&
            strokeWidth <= 2.1 &&
            (!Number.isFinite(attrStrokeWidth) || Math.abs(attrStrokeWidth - 2) <= 0.01) &&
            style.strokeLinecap === "round" &&
            style.strokeLinejoin === "round" &&
            (path.getAttribute("vector-effect") === "non-scaling-stroke" || style.vectorEffect === "non-scaling-stroke");
          const ok = parsed.commandOk && endpointOk && controlOk && styleOk && !labelOverlap && !markerIssue;
          return {
            index,
            ok,
            d,
            parentId,
            childId,
            strokeWidth: round(strokeWidth),
            attrStrokeWidth: Number.isFinite(attrStrokeWidth) ? round(attrStrokeWidth) : null,
            linecap: style.strokeLinecap,
            linejoin: style.strokeLinejoin,
            vectorEffect: path.getAttribute("vector-effect") || style.vectorEffect,
            commands: parsed.commands,
            startDistance,
            endDistance,
            endpointOk,
            controlOk,
            styleOk,
            labelOverlap,
            markerIssue,
          };
        });
        const failures = reports.filter((item) => !item.ok);
        return {
          inspectedCount: reports.length,
          failureCount: failures.length,
          strokeWidths: Array.from(new Set(reports.map((item) => item.strokeWidth).filter(Number.isFinite))).sort((a, b) => a - b),
          failureSamples: failures.slice(0, 3),
          samples: reports.slice(0, 3),
        };
      };
`;

const failures = [];
const routeSummaries = [];
let viteProcess;
let chromeProcess;
let userDataDir;

function info(message) {
  console.log(`[acceptance] ${message}`);
}

function fail(message) {
  failures.push(message);
  console.error(`[acceptance] FAIL ${message}`);
}

function extractSourceBetween(source, start, end) {
  const startIndex = source.indexOf(start);
  const endIndex = source.indexOf(end, startIndex);
  if (startIndex === -1 || endIndex === -1 || endIndex <= startIndex) {
    fail(`component registry missing section ${start}`);
    return "";
  }

  return source.slice(startIndex, endIndex);
}

function parseRegistryItems(sectionSource) {
  return Array.from(
    sectionSource.matchAll(
      /id:\s*"([^"]+)"[\s\S]*?name:\s*"([^"]+)"[\s\S]*?implementationStatus:\s*"([^"]+)"[\s\S]*?docsStatus:\s*"([^"]+)"/g,
    ),
    (match) => ({
      id: match[1],
      name: match[2],
      implementationStatus: match[3],
      docsStatus: match[4],
    }),
  );
}

function hasSampleCodeSignal(source) {
  return /(一行样例|单行样例|样例统一一行|one-line|single-line|oneLine|one-line sample|single-line sample|code:\s*`|<pre[\s>]|<code[\s>]|<CodeBlock\s+code=)/.test(
    source,
  );
}

function hasFiveExpertSignal(source) {
  const hasExplicitFiveExpert =
    /五专家|五角色|五视角|产品、UI、研发、测试.{0,8}白帽|产品、UI、研发、测试和白帽|产品：[\s\S]*UI：[\s\S]*研发：[\s\S]*测试：[\s\S]*白帽：/.test(
      source,
    );
  const hasReviewStructure = /reviewRows|expertRows|expertConclusions|acceptanceRows|验收清单|acceptanceItems/.test(source);
  const hasRoleAliases = [
    ["产品专家", 'name: "产品"', 'role: "产品"', "产品：", "产品,", "产品"],
    ["UI 专家", "UI专家", 'name: "UI"', 'role: "UI"', "UI：", "UI"],
    ["研发专家", "前端专家", 'name: "研发"', 'role: "研发"', "研发：", "研发"],
    ["测试专家", 'name: "测试"', 'role: "测试"', "测试：", "测试", "验收"],
    ["白帽专家", "白帽", "Security", "安全"],
  ].every((labels) => labels.some((label) => source.includes(label)));
  const hasSectionInferredRoles = [
    /何时使用|用途|purpose|when/i,
    /Design Token|移动端|Mobile|UI|视觉/,
    /API|Semantic DOM|自有实现|实现|registry/,
    /代码演示|示例|验收|smoke|acceptance/i,
    /安全|Security|白帽|dangerouslySetInnerHTML|禁用依赖|antd|Ant Design|禁用|外部 UI/,
  ].every((pattern) => pattern.test(source));

  return hasExplicitFiveExpert || (hasReviewStructure && hasRoleAliases) || hasSectionInferredRoles;
}

function runOwnerMatrixStaticChecks() {
  info("running owner matrix static checks");
  const registrySource = readFileSync("src/docs/componentRegistry.ts", "utf8");
  const appSource = readFileSync("src/App.tsx", "utf8");
  const docsIndexSource = readFileSync("src/docs/index.ts", "utf8");
  const acceptanceSource = readFileSync("scripts/acceptance.mjs", "utf8");

  const baseItems = parseRegistryItems(
    extractSourceBetween(registrySource, "export const componentItems", "export const componentGroups"),
  );
  const customItems = parseRegistryItems(
    extractSourceBetween(registrySource, "export const customComponents", "export const businessComponents"),
  );
  const businessItems = parseRegistryItems(
    extractSourceBetween(registrySource, "export const businessComponents", "export const chartComponents"),
  );
  const chartItems = parseRegistryItems(
    extractSourceBetween(registrySource, "export const chartComponents", "export const docsComponentItems"),
  );
  const allItems = [...baseItems, ...customItems, ...businessItems, ...chartItems];
  const duplicateIds = allItems
    .map((item) => item.id)
    .filter((id, index, ids) => ids.indexOf(id) !== index);
  const missingProductionReady = allItems.filter(
    (item) => item.implementationStatus !== "production" || item.docsStatus !== "ready",
  );
  const missingDocFiles = allItems.filter((item) => !existsSync(`src/docs/${item.name}Doc.tsx`));
  const missingRoutes = allItems.filter((item) => !appSource.includes(`selectedPage === "${item.id}"`));
  const missingExports = allItems.filter((item) => !docsIndexSource.includes(`${item.name}Doc`));
  const missingCodeSample = allItems.filter((item) => {
    const docSource = readFileSync(`src/docs/${item.name}Doc.tsx`, "utf8");
    return !hasSampleCodeSignal(docSource);
  });
  const missingFiveExpertCopy = allItems.filter((item) => {
    const docSource = readFileSync(`src/docs/${item.name}Doc.tsx`, "utf8");
    return !hasFiveExpertSignal(docSource);
  });

  if (allItems.length !== 101 || baseItems.length + customItems.length !== 75 || businessItems.length !== 11 || chartItems.length !== 15) {
    fail(
      `owner matrix expected 101 sidebar components as Base 75 / Business 11 / Charts 15, saw total=${allItems.length}, base=${baseItems.length + customItems.length}, business=${businessItems.length}, charts=${chartItems.length}`,
    );
  }
  if (duplicateIds.length > 0) {
    fail(`owner matrix duplicate component ids: ${duplicateIds.join(", ")}`);
  }
  if (missingProductionReady.length > 0) {
    fail(
      `owner matrix non production/ready entries: ${missingProductionReady
        .map((item) => `${item.id}:${item.implementationStatus}/${item.docsStatus}`)
        .join(", ")}`,
    );
  }
  if (missingDocFiles.length > 0) {
    fail(`owner matrix missing independent doc files: ${missingDocFiles.map((item) => item.id).join(", ")}`);
  }
  if (missingRoutes.length > 0) {
    fail(`owner matrix missing explicit App routes: ${missingRoutes.map((item) => item.id).join(", ")}`);
  }
  if (missingExports.length > 0) {
    fail(`owner matrix missing docs barrel exports: ${missingExports.map((item) => item.id).join(", ")}`);
  }
  if (missingCodeSample.length > 0) {
    fail(`owner matrix missing sample code signal: ${missingCodeSample.map((item) => item.id).join(", ")}`);
  }
  if (missingFiveExpertCopy.length > 0) {
    fail(`owner matrix missing five-expert copy: ${missingFiveExpertCopy.map((item) => item.id).join(", ")}`);
  }
  if (!existsSync("src/docs/CheckboxDoc.tsx") || !existsSync("src/docs/RadioDoc.tsx")) {
    fail("CheckboxDoc.tsx and RadioDoc.tsx must both exist as independent docs");
  }
  if (!appSource.includes('selectedPage === "checkbox"') || !appSource.includes('selectedPage === "radio"')) {
    fail("Checkbox and Radio must keep independent App routes");
  }
  if (existsSync("src/docs/ChoiceControlsDoc.tsx") || /ChoiceControlsDoc|choice-controls/.test(registrySource + docsIndexSource + appSource)) {
    fail("ChoiceControlsDoc must not exist; Checkbox and Radio stay separate");
  }
  if (!acceptanceSource.includes("runCheckboxChecks") || !acceptanceSource.includes("runRadioChecks")) {
    fail("acceptance must retain dedicated Checkbox and Radio checks");
  }
}

function assertSourceContains(filePath, patterns) {
  const source = readFileSync(filePath, "utf8");
  for (const pattern of patterns) {
    const matched = pattern instanceof RegExp ? pattern.test(source) : source.includes(pattern);
    if (!matched) {
      fail(`${filePath} missing performance guard ${pattern.toString()}`);
    }
  }
}

function assertSourceExcludes(filePath, patterns) {
  const source = readFileSync(filePath, "utf8");
  for (const pattern of patterns) {
    const matched = pattern instanceof RegExp ? pattern.test(source) : source.includes(pattern);
    if (matched) {
      fail(`${filePath} contains forbidden source ${pattern.toString()}`);
    }
  }
}

async function isBrowserSourceImportAvailable(client, sourcePath) {
  return evaluate(
    client,
    `(() => {
      const sourcePath = ${JSON.stringify(sourcePath)};
      if (!sourcePath.startsWith("/src/")) return false;
      const scriptSources = Array.from(document.scripts).map((script) => script.getAttribute("src") || "");
      return Boolean(window.__vite_plugin_react_preamble_installed__) || scriptSources.some((src) => src.startsWith("/src/"));
    })()`,
  );
}

